SCENE w=480 h=480 fit=contain
DEFS {
    GL id=theme_brand units=bbox x1=0 y1=0 x2=0 y2=1 stops=[[0,#1D4F7F],[1,#0D3B6A]]
    GL id=theme_row units=bbox x1=0 y1=0 x2=0 y2=1 stops=[[0,#3B3B45],[1,#32323A]]
}
# widget header hdr1 {"x":24,"y":0,"w":432,"h":64,"title":"Overview","clock":false,"counts":true,"keys":{}}
G id=hdr1 {
    R x=25.5 y=1.5 w=429 h=61 rx=12.5 f=@theme_brand s=#FF772D sw=3
    G v==gt($hdr1_crit,0) {
        C cx=372 cy=32 rx=9 ry=9 f=#F7777A sh=[[0,0,10,0,#F7777A]]
        T x=391 y=15 w=47 h=34 text="{$hdr1_crit:%.0f}" size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=right valign=middle
    }
    G v==gt($hdr1_warn,0) {
        C cx=281 cy=32 rx=9 ry=9 f=#F2B233 sh=[[0,0,10,0,#F2B233]]
        T x=300 y=15 w=47 h=34 text="{$hdr1_warn:%.0f}" size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=right valign=middle
    }
    T x=42 y=6 w=204 h=52 text=OVERVIEW size=36 font="Barlow Condensed Bold" cspace=4.17 f=#FFFFFF sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis
}
# widget readout ro1 {"x":24,"y":80,"w":432,"h":258.2,"variant":"hero","caption":"Label","unit":"%","fmt":"%.0f","bar":true,"subFmt":"","keys":{}}
G id=ro1 {
    R x=24.5 y=257.7 w=431 h=29 rx=3.5 f=#111116 s=#5A5A69 sw=1
    R x=29 y=262.2 w==clamp($ro1_lvl,0,1)*422 h=20 rx=2 f==if(eq($ro1_st,1),#7FD970,if(eq($ro1_st,2),#F2B233,if(eq($ro1_st,3),#F7777A,#A6A6B4)))
    T x=24 y=80 w=360 h=187.2 text="{$ro1_v:%.0f}" size=156 font="Barlow Condensed Bold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=right valign=middle
    T x=392 y=165.5 w=64 h=89.6 text=% size=64 font="Barlow Medium" f=#A6A6B4 sh=[[0,2,2,0,#00000099]] valign=middle
    T x=24 y=299 w=432 h=39.2 text=$ro1_status size=28 font="Barlow SemiBold" f==if(eq($ro1_st,1),#7FD970,if(eq($ro1_st,2),#F2B233,if(eq($ro1_st,3),#F7777A,#A6A6B4))) sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis
}
# widget readoutrow row1 {"x":24,"y":350,"w":432,"h":50,"name":"Temperature °C","fmt1":"%.1f","fmt2":"","w1":120,"w2":80,"keys":{}}
G id=row1 {
    R x=24.5 y=350.5 w=431 h=49 rx=5.5 f=@theme_row s=#5A5A69 sw=1
    C v==1-eq($row1_st,1)-eq($row1_st,2)-eq($row1_st,3) cx=47 cy=375 rx=9 ry=9 f=#A6A6B4
    C v==eq($row1_st,1) cx=47 cy=375 rx=9 ry=9 f=#7FD970 sh=[[0,0,10,0,#7FD970]]
    C v==eq($row1_st,2) cx=47 cy=375 rx=9 ry=9 f=#F2B233 sh=[[0,0,10,0,#F2B233]]
    C v==eq($row1_st,3) cx=47 cy=375 rx=9 ry=9 f=#F7777A sh=[[0,0,10,0,#F7777A]]
    T x=66 y=350 w=246 h=50 text="Temperature °C" size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis
    T x=322 y=350 w=120 h=50 text="{$row1_r1:%.1f}" size=34 font="Barlow SemiBold" f==if(eq($row1_st,2),#F2B233,if(eq($row1_st,3),#F7777A,#FFFFFF)) sh=[[0,2,2,0,#00000099]] align=right valign=middle fit=ellipsis
}
# widget button btn1 {"x":24,"y":410,"w":200,"h":54,"states":[{"label":"Devices","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=btn1 {
    R id=btn1_hit click=1 x=24 y=410 w=200 h=54
    R x=24.5 y=410.5 w=199 h=53 rx=5.5 f=@theme_row s=#5A5A69 sw=1 fo==1-0.25*down
    T x=42 y=410 w=164 h=54 text=DEVICES size=26 font="Barlow Condensed Bold" cspace=3.85 f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
G v==lt(ver,11118) {
    R x=0 y=0 w=480 h=58 f=#000000CC
    T x=14.4 y=0 w=451.2 h=58 text="Update ScriptedScreens Vector to 0.11.118 or newer" size=26 f=#FFCC00
}

SCENE w=480 h=480 fit=contain
DEFS {
    GL id=theme_brand units=bbox x1=0 y1=0 x2=0 y2=1 stops=[[0,#1D4F7F],[1,#0D3B6A]]
    GL id=theme_row units=bbox x1=0 y1=0 x2=0 y2=1 stops=[[0,#3B3B45],[1,#32323A]]
}
# widget header vbhdr {"x":24,"y":24,"w":432,"h":64,"title":"Devices","clock":false,"counts":false,"keys":{}}
G id=vbhdr {
    R x=25.5 y=25.5 w=429 h=61 rx=12.5 f=@theme_brand s=#FF772D sw=3
    T x=42 y=30 w=386 h=52 text=DEVICES size=36 font="Barlow Condensed Bold" cspace=4.17 f=#FFFFFF sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis
}
# widget repeater vbdev {"x":24,"y":100,"w":432,"h":162,"max":3,"layout":"list","cols":2,"pitch":56,"item":"row","fmt":"","valueW":0,"click":true,"fade":false,"keys":{}}
G id=vbdev {
    R x=24 y=100 w=432 h=162
    RP n=3 {
        G v==lt(i,$vbdev_n) {
            R id=vbdev_r click=1 x=24 y==100+i*56 w=432 h=50
            R x=24.5 y==100+i*56+0.5 w=431 h=49 rx=5.5 f=@theme_row s=#5A5A69 sw=1
            C v==1-eq($vbdev_st[i],1)-eq($vbdev_st[i],2)-eq($vbdev_st[i],3) cx=47 cy==100+i*56+25 rx=9 ry=9 f=#A6A6B4
            C v==eq($vbdev_st[i],1) cx=47 cy==100+i*56+25 rx=9 ry=9 f=#7FD970 sh=[[0,0,10,0,#7FD970]]
            C v==eq($vbdev_st[i],2) cx=47 cy==100+i*56+25 rx=9 ry=9 f=#F2B233 sh=[[0,0,10,0,#F2B233]]
            C v==eq($vbdev_st[i],3) cx=47 cy==100+i*56+25 rx=9 ry=9 f=#F7777A sh=[[0,0,10,0,#F7777A]]
            T x=66 y==100+i*56 w==lerp(236,376,clamp(and($vbdev_ready,eq($vbdev_hasv[i],0)),0,1)) h=50 text="$vbdev_name[i]" size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis missing=""
            T v==not(and($vbdev_ready,eq($vbdev_hasv[i],0))) x=312 y==100+i*56 w=130 h=50 text="{$vbdev_v[i]:%.1f}" size=34 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=right valign=middle
        }
    }
}
# widget text vbmsg {"x":24,"y":284,"w":432,"h":40,"style":"value","text":"$vbdev_msg","align":"left","state":false,"keys":{}}
G id=vbmsg {
    T x=24 y=284 w=432 h=40 text=$vbdev_msg size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis
}
# widget text vbpg {"x":172,"y":343,"w":136,"h":40,"style":"value","text":"$vbdev_pg","align":"center","state":false,"keys":{}}
G id=vbpg {
    T x=172 y=343 w=136 h=40 text=$vbdev_pg size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget button vbprev {"x":24,"y":336,"w":136,"h":54,"states":[{"label":"PREV","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=vbprev {
    R id=vbprev_hit click=1 x=24 y=336 w=136 h=54
    R x=24.5 y=336.5 w=135 h=53 rx=5.5 f=@theme_row s=#5A5A69 sw=1 fo==1-0.25*down
    T x=42 y=336 w=100 h=54 text=PREV size=26 font="Barlow Condensed Bold" cspace=3.85 f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget button vbnext {"x":320,"y":336,"w":136,"h":54,"states":[{"label":"NEXT","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=vbnext {
